import { supabase } from '../lib/supabase';

const API_ORIGIN = (import.meta.env.VITE_WERSEE_API_URL || 'https://api.wersee.com').replace(/\/+$/, '');
const MIGRATION_API = `${API_ORIGIN}/intergrations/gumroad/migration`;

export type GumroadProduct = {
  externalId: string;
  source: 'gumroad';
  name: string;
  description: string;
  shortDescription: string;
  price: number;
  currency: string;
  thumbnail: string | null;
  images: string[];
  published: boolean;
  variants: Array<{ name: string; options: Array<Record<string, unknown>> }>;
  category: string;
  productType: 'digital' | 'physical';
  sourceUrl: string | null;
};

export type MigrationProductStatus = {
  productId: string;
  name: string | null;
  descriptionStatus: string;
  imagesFound: number;
  imagesTransferred: number;
  productCreationStatus: string;
  duplicate: boolean;
  errorCode: string | null;
  retryable: boolean;
};

export type MigrationStatus = {
  success: true;
  provider: 'gumroad';
  status: 'created' | 'connecting' | 'connected' | 'selected' | 'claimed' | 'importing' | 'completed' | 'error' | 'expired';
  connected: boolean;
  claimed: boolean;
  selectedProductIds: string[];
  expiresAt: string;
  report: {
    imported: number;
    skipped: number;
    updated: number;
    imagesTransferred: number;
    imageErrors: Array<{ image: number; code: string }>;
    errors: Array<{ productId: string; code: string }>;
    total: number;
    finished: number;
  };
  products: MigrationProductStatus[];
};

class MigrationApiError extends Error {
  constructor(public readonly code: string, message: string, public readonly status: number) {
    super(message);
  }
}

const request = async <T>(path: string, init: RequestInit = {}, accessToken?: string) => {
  const response = await fetch(`${MIGRATION_API}${path}`, {
    ...init,
    credentials: 'include',
    headers: {
      Accept: 'application/json',
      ...(init.body ? { 'Content-Type': 'application/json' } : {}),
      ...(accessToken ? { Authorization: `Bearer ${accessToken}` } : {}),
      ...init.headers,
    },
  });
  const body = await response.json().catch(() => ({})) as Record<string, any>;
  if (!response.ok) {
    throw new MigrationApiError(
      String(body.error?.code || 'MIGRATION_REQUEST_FAILED'),
      String(body.error?.message || 'The migration request could not be completed.'),
      response.status,
    );
  }
  return body as T;
};

const accessToken = async () => {
  const { data, error } = await supabase.auth.getSession();
  if (error || !data.session?.access_token) throw new MigrationApiError('AUTHENTICATION_REQUIRED', 'Sign in to continue the import.', 401);
  return data.session.access_token;
};

export const gumroadMigration = {
  createSession: () => request<MigrationStatus>('/session', { method: 'POST', body: '{}' }),
  status: () => request<MigrationStatus>('/status'),
  connect: () => request<{ authorizationUrl: string; expiresAt: string }>('/connect'),
  products: () => request<{ success: true; products: GumroadProduct[] }>('/products'),
  select: (productIds: string[]) => request<MigrationStatus>('/select', {
    method: 'POST', body: JSON.stringify({ productIds }),
  }),
  claim: async () => request<MigrationStatus>('/claim', { method: 'POST', body: '{}' }, await accessToken()),
  importStep: async () => request<MigrationStatus>('/import', { method: 'POST', body: '{}' }, await accessToken()),
  retryImages: async (productId: string) => request<MigrationStatus>('/retry-images', {
    method: 'POST', body: JSON.stringify({ productIds: [productId] }),
  }, await accessToken()),
};

