import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  ArrowRight, Check, CheckCircle2, ChevronRight, CircleAlert, CloudUpload,
  ExternalLink, Image as ImageIcon, Loader2, LockKeyhole, PackageCheck,
  RefreshCw, ShieldCheck, Sparkles,
} from 'lucide-react';
import { Link } from 'react-router-dom';
import { SEO } from '../components/SEO';
import { supabase } from '../lib/supabase';
import { buildAuthEntryUrl } from '../lib/authRouting';
import {
  gumroadMigration,
  type GumroadProduct,
  type MigrationProductStatus,
  type MigrationStatus,
} from '../services/gumroadMigration';

const stages = [
  'Connecting to Gumroad',
  'Loading products',
  'Preparing your Wersee account',
  'Importing product details',
  'Transferring images to Wersee storage',
  'Creating draft products',
  'Finishing migration',
];

const money = (minorUnits: number, currency: string) => new Intl.NumberFormat('en', {
  style: 'currency', currency: currency || 'USD',
}).format(minorUnits / (['JPY', 'KRW'].includes(currency) ? 1 : 100));

const statusLabel = (product: MigrationProductStatus) => {
  if (product.duplicate) return 'Skipped duplicate';
  if (product.productCreationStatus === 'imported') return 'Draft created';
  if (product.productCreationStatus === 'failed') return 'Needs attention';
  if (product.productCreationStatus === 'processing') return 'Importing';
  return 'Queued';
};

const GumroadMark = () => (
  <span aria-hidden="true" className="grid h-11 w-11 place-items-center rounded-2xl bg-[#ff90e8] text-xl font-black text-black shadow-[inset_0_-2px_0_rgba(0,0,0,.12)]">G</span>
);

export const MoveFromGumroad = () => {
  const [migration, setMigration] = useState<MigrationStatus | null>(null);
  const [products, setProducts] = useState<GumroadProduct[]>([]);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [signedIn, setSignedIn] = useState(false);
  const [busy, setBusy] = useState<'session' | 'connect' | 'products' | 'select' | 'claim' | 'import' | 'retry' | null>('session');
  const [stage, setStage] = useState(stages[0]);
  const [error, setError] = useState<string | null>(null);
  const mounted = useRef(true);

  const loadProducts = async () => {
    setBusy('products');
    setStage(stages[1]);
    const result = await gumroadMigration.products();
    if (!mounted.current) return;
    setProducts(result.products);
    setSelected((current) => current.size ? current : new Set(result.products.map((product) => product.externalId)));
    setBusy(null);
  };

  useEffect(() => {
    mounted.current = true;
    void Promise.all([
      gumroadMigration.createSession(),
      supabase.auth.getSession(),
    ]).then(async ([session, auth]) => {
      if (!mounted.current) return;
      setMigration(session);
      setSignedIn(Boolean(auth.data.session));
      setSelected(new Set(session.selectedProductIds));
      setBusy(null);
      if (session.connected) await loadProducts();
    }).catch((caught: unknown) => {
      if (!mounted.current) return;
      setError(caught instanceof Error ? caught.message : 'The migration session could not be started.');
      setBusy(null);
    });
    const { data } = supabase.auth.onAuthStateChange((_event, session) => setSignedIn(Boolean(session)));
    return () => { mounted.current = false; data.subscription.unsubscribe(); };
  }, []);

  const allSelected = products.length > 0 && selected.size === products.length;
  const chosenProducts = useMemo(() => products.filter((product) => selected.has(product.externalId)), [products, selected]);
  const needsAccount = migration?.status === 'selected' && !migration.claimed;
  const canImport = Boolean(migration?.claimed && migration.report.total > 0 && migration.status !== 'completed');
  const progress = migration?.report.total
    ? Math.round((migration.report.finished / migration.report.total) * 100)
    : 0;

  const connect = async () => {
    setBusy('connect');
    setStage(stages[0]);
    setError(null);
    try {
      const result = await gumroadMigration.connect();
      window.location.assign(result.authorizationUrl);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'Gumroad could not be connected.');
      setBusy(null);
    }
  };

  const saveSelection = async () => {
    if (!selected.size) return;
    setBusy('select');
    setStage(stages[2]);
    setError(null);
    try {
      const result = await gumroadMigration.select([...selected]);
      setMigration(result);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'The product selection could not be saved.');
    } finally {
      setBusy(null);
    }
  };

  const claim = async () => {
    setBusy('claim');
    setStage(stages[2]);
    setError(null);
    try {
      const result = await gumroadMigration.claim();
      setMigration(result);
      return result;
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'The migration could not be attached to your account.');
      return null;
    } finally {
      setBusy(null);
    }
  };

  const runImport = async (initial?: MigrationStatus | null) => {
    setBusy('import');
    setError(null);
    let current = initial || migration;
    try {
      for (let step = 0; step < 52 && current && current.report.finished < current.report.total; step += 1) {
        const item = current.products.find((product) => product.productCreationStatus === 'processing');
        setStage(item?.imagesFound && item.imagesTransferred < item.imagesFound ? stages[4] : stages[3]);
        current = await gumroadMigration.importStep();
        if (!mounted.current) return;
        setMigration(current);
      }
      if (current && current.status !== 'completed') {
        setStage(stages[6]);
        current = await gumroadMigration.importStep();
        if (mounted.current) setMigration(current);
      }
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'The import paused after a server error. You can safely resume it.');
    } finally {
      if (mounted.current) setBusy(null);
    }
  };

  const retryImages = async (productId: string) => {
    setBusy('retry');
    setStage(stages[4]);
    setError(null);
    try {
      setMigration(await gumroadMigration.retryImages(productId));
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'The image transfer could not be retried.');
    } finally {
      setBusy(null);
    }
  };

  const authReturn = typeof window === 'undefined' ? 'https://www.wersee.com/move-from-gumroad' : window.location.href;
  const signInUrl = buildAuthEntryUrl('/auth', authReturn);
  const createAccountUrl = buildAuthEntryUrl('/auth?mode=signup', authReturn);

  return (
    <div className="min-h-screen bg-[#f5f5f3] text-[#171717] dark:bg-[#080808] dark:text-white">
      <SEO
        title="Move Gumroad products to Wersee"
        description="Bring your products, descriptions, images, prices and options to Wersee."
        url="https://www.wersee.com/move-from-gumroad"
      />

      <section className="relative overflow-hidden border-b border-black/[0.07] bg-white px-4 pb-16 pt-14 dark:border-white/[0.08] dark:bg-[#0b0b0b] sm:px-6 sm:pb-20 sm:pt-20">
        <div aria-hidden="true" className="absolute left-1/2 top-[-18rem] h-[34rem] w-[52rem] -translate-x-1/2 rounded-full bg-[radial-gradient(circle,rgba(255,144,232,.2),transparent_68%)]" />
        <div className="relative mx-auto max-w-5xl text-center">
          <div className="mx-auto flex w-fit items-center gap-2 rounded-full border border-black/10 bg-white/80 p-1.5 pr-4 shadow-sm backdrop-blur dark:border-white/10 dark:bg-white/[0.05]">
            <GumroadMark />
            <ChevronRight className="h-4 w-4 text-black/35 dark:text-white/35" />
            <img src="/brand/wersee-icon-192.png" alt="Wersee" className="h-11 w-11 rounded-2xl object-cover" />
            <span className="text-xs font-semibold text-black/55 dark:text-white/55">Secure product transfer</span>
          </div>
          <h1 className="mx-auto mt-8 max-w-4xl text-4xl font-semibold tracking-[-0.05em] sm:text-6xl lg:text-7xl">
            Move Gumroad products to Wersee
          </h1>
          <p className="mx-auto mt-6 max-w-2xl text-base leading-7 text-black/55 dark:text-white/55 sm:text-lg">
            Bring your products, descriptions, images, prices and options to Wersee.
          </p>
          {!migration?.connected && (
            <button
              type="button"
              onClick={connect}
              disabled={Boolean(busy)}
              className="mt-9 inline-flex min-h-14 items-center gap-3 rounded-full bg-black px-7 text-sm font-semibold text-white shadow-xl transition hover:-translate-y-0.5 disabled:cursor-wait disabled:opacity-60 dark:bg-white dark:text-black"
            >
              {busy === 'connect' ? <Loader2 className="h-4 w-4 animate-spin" /> : <GumroadMark />}
              Connect Gumroad
              <ArrowRight className="h-4 w-4" />
            </button>
          )}
          <div className="mx-auto mt-8 flex max-w-2xl flex-wrap items-center justify-center gap-x-5 gap-y-2 text-xs text-black/45 dark:text-white/45">
            <span className="inline-flex items-center gap-1.5"><LockKeyhole className="h-3.5 w-3.5" /> Tokens stay server-side</span>
            <span className="inline-flex items-center gap-1.5"><ShieldCheck className="h-3.5 w-3.5" /> Drafts by default</span>
            <span className="inline-flex items-center gap-1.5"><CloudUpload className="h-3.5 w-3.5" /> Images move to Wersee storage</span>
          </div>
        </div>
      </section>

      <main className="mx-auto w-full max-w-6xl space-y-6 px-4 py-10 sm:px-6 sm:py-14">
        {error && (
          <div role="alert" className="flex items-start gap-3 rounded-[1.4rem] border border-red-200 bg-red-50 p-4 text-sm text-red-800 dark:border-red-400/20 dark:bg-red-500/10 dark:text-red-200">
            <CircleAlert className="mt-0.5 h-5 w-5 shrink-0" />
            <div><p className="font-semibold">Migration paused</p><p className="mt-1 opacity-80">{error}</p></div>
          </div>
        )}

        {busy && (
          <div aria-live="polite" className="flex items-center gap-3 rounded-full border border-black/[0.08] bg-white px-5 py-3 text-sm shadow-sm dark:border-white/10 dark:bg-white/[0.04]">
            <Loader2 className="h-4 w-4 animate-spin text-[#ff4fc4]" />
            <span className="font-medium">{stage}</span>
          </div>
        )}

        {migration?.connected && products.length > 0 && !migration.claimed && !needsAccount && (
          <section aria-labelledby="choose-products" className="rounded-[2rem] border border-black/[0.08] bg-white p-5 shadow-sm dark:border-white/10 dark:bg-[#101010] sm:p-7">
            <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
              <div>
                <p className="text-xs font-semibold uppercase tracking-[0.16em] text-[#d52aa6]">Gumroad connected</p>
                <h2 id="choose-products" className="mt-2 text-2xl font-semibold tracking-[-0.035em]">Choose what to move</h2>
                <p className="mt-2 text-sm text-black/50 dark:text-white/50">Every selected product is checked again directly with Gumroad during import.</p>
              </div>
              <button type="button" onClick={() => setSelected(allSelected ? new Set() : new Set(products.map((product) => product.externalId)))} className="min-h-11 rounded-full border border-black/10 px-4 text-sm font-semibold dark:border-white/12">
                {allSelected ? 'Clear selection' : 'Select all'}
              </button>
            </div>
            <div className="mt-6 grid gap-3 sm:grid-cols-2">
              {products.map((product) => {
                const checked = selected.has(product.externalId);
                return (
                  <label key={product.externalId} className={`group flex cursor-pointer gap-4 rounded-[1.35rem] border p-4 transition ${checked ? 'border-[#ff77d8] bg-[#fff4fc] dark:border-[#ff77d8]/50 dark:bg-[#ff77d8]/[0.07]' : 'border-black/[0.07] hover:border-black/20 dark:border-white/[0.08] dark:hover:border-white/20'}`}>
                    <input
                      type="checkbox"
                      checked={checked}
                      onChange={() => setSelected((current) => {
                        const next = new Set(current);
                        if (next.has(product.externalId)) next.delete(product.externalId); else next.add(product.externalId);
                        return next;
                      })}
                      className="sr-only"
                    />
                    <span className={`mt-1 grid h-6 w-6 shrink-0 place-items-center rounded-full border ${checked ? 'border-[#df32af] bg-[#df32af] text-white' : 'border-black/20 dark:border-white/25'}`}>
                      {checked && <Check className="h-3.5 w-3.5" />}
                    </span>
                    {product.thumbnail ? <img src={product.thumbnail} alt="" className="h-20 w-20 shrink-0 rounded-2xl object-cover" referrerPolicy="no-referrer" /> : <span className="grid h-20 w-20 shrink-0 place-items-center rounded-2xl bg-black/[0.04] dark:bg-white/[0.06]"><ImageIcon className="h-5 w-5 opacity-35" /></span>}
                    <span className="min-w-0 flex-1">
                      <span className="block truncate font-semibold">{product.name}</span>
                      <span className="mt-1 line-clamp-2 block text-xs leading-5 text-black/50 dark:text-white/50">{product.shortDescription || 'No short description'}</span>
                      <span className="mt-3 flex flex-wrap gap-2 text-[11px] font-medium text-black/45 dark:text-white/45">
                        <span>{money(product.price, product.currency)}</span><span>•</span>
                        <span>{product.images.length} image{product.images.length === 1 ? '' : 's'}</span><span>•</span>
                        <span>{product.variants.reduce((sum, variant) => sum + variant.options.length, 0)} option{product.variants.reduce((sum, variant) => sum + variant.options.length, 0) === 1 ? '' : 's'}</span>
                      </span>
                    </span>
                  </label>
                );
              })}
            </div>
            <div className="mt-6 flex flex-col gap-3 rounded-[1.35rem] bg-black/[0.035] p-4 dark:bg-white/[0.045] sm:flex-row sm:items-center sm:justify-between">
              <p className="text-sm text-black/55 dark:text-white/55"><strong className="text-black dark:text-white">{selected.size}</strong> of {products.length} products selected. Draft products only; sales history is never imported.</p>
              <button type="button" disabled={!selected.size || Boolean(busy)} onClick={saveSelection} className="inline-flex min-h-12 items-center justify-center gap-2 rounded-full bg-black px-5 text-sm font-semibold text-white disabled:opacity-40 dark:bg-white dark:text-black">
                Continue <ArrowRight className="h-4 w-4" />
              </button>
            </div>
          </section>
        )}

        {needsAccount && (
          <section aria-labelledby="account-step" className="rounded-[2rem] border border-black/[0.08] bg-white p-6 text-center shadow-sm dark:border-white/10 dark:bg-[#101010] sm:p-10">
            <span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-black text-white dark:bg-white dark:text-black"><ShieldCheck className="h-6 w-6" /></span>
            <h2 id="account-step" className="mt-5 text-2xl font-semibold tracking-[-0.035em]">Attach the migration to your Wersee account</h2>
            <p className="mx-auto mt-3 max-w-xl text-sm leading-6 text-black/50 dark:text-white/50">Your Gumroad products are ready. Wersee will only create permanent draft products after a verified sign-in.</p>
            <div className="mx-auto mt-7 flex max-w-md flex-col gap-3 sm:flex-row">
              {signedIn ? (
                <button type="button" disabled={Boolean(busy)} onClick={() => void claim().then((result) => result && runImport(result))} className="inline-flex min-h-12 flex-1 items-center justify-center gap-2 rounded-full bg-black px-5 text-sm font-semibold text-white dark:bg-white dark:text-black">
                  Continue with Wersee <ArrowRight className="h-4 w-4" />
                </button>
              ) : (
                <>
                  <a href={signInUrl} className="inline-flex min-h-12 flex-1 items-center justify-center rounded-full border border-black/12 px-5 text-sm font-semibold dark:border-white/15">Sign in to Wersee</a>
                  <a href={createAccountUrl} className="inline-flex min-h-12 flex-1 items-center justify-center rounded-full bg-black px-5 text-sm font-semibold text-white dark:bg-white dark:text-black">Create a Wersee account</a>
                </>
              )}
            </div>
          </section>
        )}

        {(migration?.claimed || migration?.status === 'completed') && (
          <section aria-labelledby="import-progress" className="rounded-[2rem] border border-black/[0.08] bg-white p-5 shadow-sm dark:border-white/10 dark:bg-[#101010] sm:p-7">
            <div className="flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between">
              <div>
                <p className="text-xs font-semibold uppercase tracking-[0.16em] text-[#d52aa6]">{migration.status === 'completed' ? 'Migration complete' : 'Secure import'}</p>
                <h2 id="import-progress" className="mt-2 text-2xl font-semibold tracking-[-0.035em]">{migration.status === 'completed' ? 'Your draft products are ready' : 'Moving products to Wersee'}</h2>
              </div>
              {canImport && <button type="button" disabled={Boolean(busy)} onClick={() => runImport()} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-full bg-black px-5 text-sm font-semibold text-white dark:bg-white dark:text-black">{migration.report.finished ? 'Resume import' : 'Start import'} <ArrowRight className="h-4 w-4" /></button>}
            </div>
            <div className="mt-6 h-2 overflow-hidden rounded-full bg-black/[0.06] dark:bg-white/[0.08]"><div className="h-full rounded-full bg-gradient-to-r from-[#ff5fcf] to-[#7c5cff] transition-[width] duration-500" style={{ width: `${progress}%` }} /></div>
            <div className="mt-2 flex justify-between text-xs text-black/45 dark:text-white/45"><span>{migration.report.finished} of {migration.report.total} products finished</span><span>{progress}%</span></div>

            <div className="mt-6 divide-y divide-black/[0.06] overflow-hidden rounded-[1.35rem] border border-black/[0.07] dark:divide-white/[0.07] dark:border-white/[0.08]">
              {migration.selectedProductIds.map((productId) => {
                const source = products.find((product) => product.externalId === productId);
                const item = migration.products.find((product) => product.productId === productId);
                return (
                  <div key={productId} className="flex flex-col gap-4 p-4 sm:flex-row sm:items-center">
                    <span className={`grid h-10 w-10 shrink-0 place-items-center rounded-full ${item?.productCreationStatus === 'imported' || item?.duplicate ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-400/10 dark:text-emerald-300' : item?.productCreationStatus === 'failed' ? 'bg-red-100 text-red-700 dark:bg-red-400/10 dark:text-red-300' : 'bg-black/[0.04] dark:bg-white/[0.06]'}`}>
                      {item?.productCreationStatus === 'imported' || item?.duplicate ? <CheckCircle2 className="h-5 w-5" /> : item?.productCreationStatus === 'failed' ? <CircleAlert className="h-5 w-5" /> : <Loader2 className={`h-4 w-4 ${busy === 'import' ? 'animate-spin' : ''}`} />}
                    </span>
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-sm font-semibold">{item?.name || source?.name || 'Gumroad product'}</p>
                      <div className="mt-1 flex flex-wrap gap-x-4 gap-y-1 text-xs text-black/45 dark:text-white/45">
                        <span>Description: {item?.descriptionStatus || 'pending'}</span>
                        <span>Images: {item?.imagesTransferred || 0}/{item?.imagesFound ?? source?.images.length ?? 0}</span>
                        <span>Status: {item ? statusLabel(item) : 'Queued'}</span>
                      </div>
                    </div>
                    {item?.retryable && item.productCreationStatus === 'imported' && <button type="button" disabled={Boolean(busy)} onClick={() => retryImages(productId)} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-full border border-black/10 px-4 text-xs font-semibold dark:border-white/12"><RefreshCw className="h-3.5 w-3.5" /> Retry images</button>}
                  </div>
                );
              })}
            </div>

            {migration.status === 'completed' && (
              <div className="mt-6 grid gap-4 lg:grid-cols-[1fr_auto] lg:items-center">
                <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
                  {[
                    ['Imported', migration.report.imported], ['Skipped', migration.report.skipped],
                    ['Updated', migration.report.updated], ['Images moved', migration.report.imagesTransferred],
                  ].map(([label, value]) => <div key={String(label)} className="rounded-2xl bg-black/[0.035] p-4 dark:bg-white/[0.045]"><p className="text-2xl font-semibold">{value}</p><p className="mt-1 text-xs text-black/45 dark:text-white/45">{label}</p></div>)}
                </div>
                <Link to="/workspace/management-products" className="inline-flex min-h-12 items-center justify-center gap-2 rounded-full bg-black px-5 text-sm font-semibold text-white dark:bg-white dark:text-black">Open imported products <ExternalLink className="h-4 w-4" /></Link>
              </div>
            )}
          </section>
        )}

        {!migration?.connected && !busy && (
          <section className="grid gap-4 sm:grid-cols-3">
            {[
              [Sparkles, 'Preview before signing up', 'Connect Gumroad and review real products before creating a Wersee account.'],
              [CloudUpload, 'Wersee-owned images', 'Supported images are validated and transferred to owner-scoped Wersee storage.'],
              [PackageCheck, 'Safe draft creation', 'Imports are idempotent and unpublished until you decide to publish them.'],
            ].map(([Icon, title, copy]) => {
              const CardIcon = Icon as React.ComponentType<{ className?: string }>;
              return <article key={String(title)} className="rounded-[1.5rem] border border-black/[0.07] bg-white p-5 dark:border-white/[0.08] dark:bg-white/[0.035]"><CardIcon className="h-5 w-5 text-[#d52aa6]" /><h2 className="mt-4 font-semibold">{String(title)}</h2><p className="mt-2 text-sm leading-6 text-black/50 dark:text-white/50">{String(copy)}</p></article>;
            })}
          </section>
        )}
      </main>
    </div>
  );
};

export default MoveFromGumroad;
